Follow this complete example.
```swift
struct DeferredNote {
    var action: (() -> String)? = nil
    mutating func store(_ action: @escaping () -> String) {
        self.action = action
    }
    func read() -> String {
        if let saved = action {
            return saved()
        }
        return "empty"
    }
}
var note = DeferredNote()
var label = "draft"
note.store { [label] in return label }
label = "revised"
print(note.read())
```
Output:
```text
draft
```

